                wrapper._checkpoint_controller.owner = nn.Identity()
            elif bad == "co_mount":
                wrapper.capsule = nn.Identity()
            else:
                return nn.Identity()
            return wrapper
    
        monkeypatch.setattr(module, "make_reference_wrapper", corrupt)
        with pytest.raises(module.ReferenceParityError):
